# =============================================================================
#  Generalized VFM / studies / constrained_d12 / make_study.py
# -----------------------------------------------------------------------------
#  The D12 >= 0 campaign, self-contained: setup table, identification, the
#  one-load-step-per-experiment check, and every figure.
#
#  Everything in this folder is generated by this one script.  Nothing outside
#  the folder is written, and nothing outside it is modified.
#
#  ROUTE (B) THROUGHOUT -- TESTS_WITH_45_RAW.  Every coupon is used in the
#  frame it was MEASURED in, and only D is rotated.  All three therefore sit
#  the way they physically sat in the fixture: length along +y, aligned with
#  the machine's y axis.  The transverse coupon has a pre-rotated twin whose
#  fields were turned +90 deg at MATLAB export time; using it gives the same
#  theta to 4.8e-14 relative, but it draws the specimen lying on its side,
#  which is not how the test was run.  For a figure that has to depict the
#  experiment, only the raw frame is honest.
#
#      python -m studies.constrained_d12.make_study
#
#  THE CONSTRAINT, IN CLOSED FORM
#  ---------------------------------------------------------------------------
#  The GLS objective is quadratic, Q(theta) = (H theta - b)^T C^-1 (H theta - b),
#  so a single inequality theta_k >= 0 has only two KKT cases:
#
#      unconstrained theta_k >= 0  ->  inactive, answer unchanged
#      unconstrained theta_k <  0  ->  ACTIVE, theta_k = 0
#
#  and with the active set known the answer is the projection onto
#  {theta_k = 0} in the information metric:
#
#      Sigma   = (H^T C^-1 H)^-1                       (the eq. (20) covariance)
#      theta_c = theta_hat - (theta_hat_k / Sigma_kk) * Sigma[:, k]
#      lambda  = theta_hat_k / Sigma_kk
#      DeltaQ  = theta_hat_k^2 / Sigma_kk              (chi^2, 1 dof, H0: D12=0)
#
#  Exact for a quadratic objective, and identical to deleting column k and
#  re-solving -- which is asserted, not assumed, in `explicit_check()`.
#
#  C depends on theta, so the projection is applied INSIDE the FGLS loop.
# =============================================================================

from __future__ import annotations

