LABELS = ["D11", "D12", "D22", "D66"]
K_D12 = 1
FIGURES = HERE / "figures"
DATA = HERE / "data"
COLOURS = {"D11": "#1F4E79", "D12": "#C55A11", "D22": "#2E7D32",
           "D66": "#7B4FA0"}
MARKERS = {"D11": "o", "D12": "s", "D22": "^", "D66": "D"}


# =============================================================================
#  Identification
# =============================================================================

def build(tests, step_index=None):
    """Cases + experiment ids.  `step_index` picks ONE load step per test."""
    cases, ids = [], []
    for spec in tests:
        paths = mat_files(spec)
        chosen = [paths[step_index]] if step_index is not None else paths
        spec_cases = build_cases(spec, paths=chosen, verbose=False)
        cases.extend(spec_cases)
        ids.extend([spec.experiment_id] * len(spec_cases))
    return cases, ids


def fgls(cases, ids, initial):
    return run_gls_identification_cases(
        cases=cases, material_type=MATERIAL_TYPE, analysis_type=ANALYSIS_TYPE,
        initial_parameters=list(initial),
        identification_settings=IdentificationSettings(
            max_iterations=40, convergence_tolerance=1.0e-8),
        linear_algebra_settings=LinearAlgebraSettings(),
        experiment_ids=ids, gls_settings=GlsSettings(), verbose=False)


def project(theta, covariance, k=K_D12):
    theta = np.asarray(theta, dtype=float)
    multiplier = theta[k] / covariance[k, k]
    return theta - multiplier * covariance[:, k], multiplier, theta[k] * multiplier


def verify_kkt(result, theta_c, k=K_D12):
    """The rigorous check, all AT ONE FIXED C -- the result's converged one.

    Comparing chi2 between the free and constrained FGLS runs is NOT a valid
    test that the constraint worsens the fit: each run converges to its OWN C,
    so they minimise different functions and either can come out lower.  The
    inequality that IS guaranteed holds at fixed C:

        Q(theta_c) >= Q(theta*)     with  theta* = argmin Q over all theta,

    and theta_c must be exactly the information-metric projection of theta*.
    Both are returned so the caller can assert them.
    """
    design, rhs, cov = (result.K_matrix, result.U_vector,
                        result.global_covariance)
    factor = cholesky(cov, lower=True)
    a = solve_triangular(factor, design, lower=True)
    b = solve_triangular(factor, rhs, lower=True)

    theta_star, *_ = np.linalg.lstsq(a, b, rcond=None)
    sigma = np.linalg.inv(a.T @ a)
    projected = theta_star - (theta_star[k] / sigma[k, k]) * sigma[:, k]

    q_of = lambda th: float(np.sum((a @ np.asarray(th, float) - b) ** 2))
    return {
        "q_star": q_of(theta_star),
        "q_constrained": q_of(theta_c),
        "projection_error": float(np.max(np.abs(projected - theta_c))),
        "sigma_error": float(np.max(np.abs(
            sigma - np.asarray(result.parameter_covariance, float)))
            / max(np.max(np.abs(sigma)), 1e-30)),
        "theta_star": theta_star,
    }


def explicit_check(result, k=K_D12):
    """The same answer by deleting column k -- an assertion, not a comment."""
    design, rhs, cov = (result.K_matrix, result.U_vector,
                        result.global_covariance)
    factor = cholesky(cov, lower=True)
    a = solve_triangular(factor, design, lower=True)
    b = solve_triangular(factor, rhs, lower=True)
    keep = [j for j in range(design.shape[1]) if j != k]
    reduced, *_ = np.linalg.lstsq(a[:, keep], b, rcond=None)
    out = np.zeros(design.shape[1])
    out[keep] = reduced
    return out


def chi2_of(result, theta, n_free_parameters):
    design, rhs, cov = (result.K_matrix, result.U_vector,
                        result.global_covariance)
    residual = design @ np.asarray(theta, dtype=float) - rhs
    dof = design.shape[0] - n_free_parameters
    return float(residual @ np.linalg.solve(cov, residual)) / dof


def identify(cases, ids):
    """Unconstrained and D12 >= 0 constrained, with the constraint diagnostics."""
    free = fgls(cases, ids, INITIAL_PARAMETERS)
    theta_free = np.asarray(free.final_parameters, dtype=float)
    n_par = free.K_matrix.shape[1]
    #  Own reduced chi2 rather than make_figures.chi_square_diagnostics: that
    #  helper also forms a PER-PARAMETER block whose denominator is
    #  (n_steps - 1), which divides by zero when only ONE load step per
    #  experiment is used.  Same definition for the total, and using one
    #  formula for both the constrained and unconstrained fit keeps them
    #  strictly comparable.
    chi2_free = chi2_of(free, theta_free, n_par)

    row = {"theta_free": theta_free, "chi2_free": chi2_free,
           "active": bool(theta_free[K_D12] < 0.0)}

    if not row["active"]:
        row.update(theta_con=theta_free.copy(), chi2_con=chi2_free,
                   delta_q=0.0, birge_q=0.0, p_value=1.0, agreement=0.0,
                   q_star=0.0, q_constrained=0.0, q_penalty=0.0,
                   projection_error=0.0, sigma_error=0.0)
        return row

    theta_c = theta_free
    result = free
    for _ in range(8):
        result = fgls(cases, ids, theta_c)
        new, multiplier, delta_q = project(result.final_parameters,
                                           result.parameter_covariance)
        if np.max(np.abs(new - theta_c)) < 1e-10:
            theta_c = new
            break
        theta_c = new

    agreement = float(np.max(np.abs(explicit_check(result) - theta_c)))
    #  The guaranteed inequality, at the ONE converged C of `result`.
    audit = verify_kkt(result, theta_c)
    if audit["q_constrained"] < audit["q_star"] - 1e-6 * max(audit["q_star"], 1.0):
        raise SystemExit(
            f"KKT VIOLATION: Q(theta_c) = {audit['q_constrained']:.6e} < "
            f"Q(theta*) = {audit['q_star']:.6e} at fixed C.")
    if audit["projection_error"] > 1e-6 * max(np.max(np.abs(theta_c)), 1.0):
        raise SystemExit(
            f"PROJECTION MISMATCH: {audit['projection_error']:.3e}")
    row["q_star"] = audit["q_star"]
    row["q_constrained"] = audit["q_constrained"]
    row["q_penalty"] = audit["q_constrained"] - audit["q_star"]
    row["projection_error"] = audit["projection_error"]
    row["sigma_error"] = audit["sigma_error"]
    chi2_con = chi2_of(result, theta_c, n_par - 1)
    #  DeltaQ is formed with the eq. (20) covariance, which the data reject at
    #  chi2/dof.  Dividing by that misfit is the Birge correction -- the same
    #  one the README applies to every error bar -- and is the statistic to
    #  quote.  Under H0 it is chi^2 with 1 dof.
    birge_q = delta_q / chi2_free
    row.update(theta_con=theta_c, chi2_con=chi2_con, delta_q=float(delta_q),
               birge_q=float(birge_q), p_value=float(exp(-0.5 * birge_q)),
               agreement=agreement)
    return row


# =============================================================================
#  Figure 1 -- the setup: windows, boundaries, boundary conditions
# =============================================================================

def experiment_setup():
    """Everything about each experiment, read from its own files."""
    rows = []
    for spec in TESTS_WITH_45_RAW:
        module = load_bc_module(spec.bc_file)
        bounds = module.MESH_SETTINGS["bounds"]
        paths = mat_files(spec)
        nodes = np.asarray(loadmat(paths[-1], squeeze_me=True)["nodes"],
                           dtype=float)
        prescribed_edges = sorted({e["edge"] for e in module.PRESCRIBED})
        loaded_edges = [e["edge"] for e in module.EXTERNAL]
        all_edges = {"top", "bottom", "left", "right"}
        free_edges = sorted(all_edges - set(prescribed_edges) - set(loaded_edges))
        length_axis = spec.length_axis
        rows.append({
            "name": spec.name,
            "experiment_id": spec.experiment_id,
            "bc_file": spec.bc_file.name,
            "n_steps": len(paths),
            "n_points": int(nodes.shape[0]),
            "mesh": f"{module.MESH_SETTINGS['number_of_elements_x']}x"
                    f"{module.MESH_SETTINGS['number_of_elements_y']}",
            "sample_area_mm2": float(module.SOLVER_SETTINGS["sample_area_total"]),
            "material_orientation_deg": spec.material_orientation_deg,
            "length_axis": length_axis,
            "x_min": float(nodes[:, 0].min()), "x_max": float(nodes[:, 0].max()),
            "y_min": float(nodes[:, 1].min()), "y_max": float(nodes[:, 1].max()),
            "mesh_x_min": bounds["x_min"], "mesh_x_max": bounds["x_max"],
            "mesh_y_min": bounds["y_min"], "mesh_y_max": bounds["y_max"],
            "window_start_mm": (float(nodes[:, 0].min()) if length_axis == "x"
                                else float(nodes[:, 1].min())),
            "window_end_mm": (float(nodes[:, 0].max()) if length_axis == "x"
                              else float(nodes[:, 1].max())),
            "length_mm": (float(np.ptp(nodes[:, 0])) if length_axis == "x"
                          else float(np.ptp(nodes[:, 1]))),
            "width_mm": (float(np.ptp(nodes[:, 1])) if length_axis == "x"
                         else float(np.ptp(nodes[:, 0]))),
            "free_edges": "+".join(free_edges),
            "loaded_edges": "+".join(sorted(set(loaded_edges))),
            "clamped_dofs": ", ".join(
                f"{e['edge']}:{e['dof']}" for e in module.PRESCRIBED),
            "external_dof": ", ".join(
                f"{e['edge']}:{e['dof']}" for e in module.EXTERNAL),
        })
    return rows


def figure_setup(rows, path):
    """The three measurement windows to scale, with their BCs marked."""
    figure, axes = plt.subplots(1, 3, figsize=(7.16, 3.45))
    for axis, row in zip(axes, rows):
        x0, x1 = row["x_min"], row["x_max"]
        y0, y1 = row["y_min"], row["y_max"]
        axis.add_patch(Rectangle((x0, y0), x1 - x0, y1 - y0,
                                 facecolor="#EDF2F7", edgecolor="none"))

        edge_line = {
            "left":   ((x0, x0), (y0, y1)),
            "right":  ((x1, x1), (y0, y1)),
            "bottom": ((x0, x1), (y0, y0)),
            "top":    ((x0, x1), (y1, y1)),
        }
        for edge, (xs, ys) in edge_line.items():
            if edge in row["loaded_edges"].split("+"):
                axis.plot(xs, ys, color="#C0392B", lw=2.6, solid_capstyle="butt",
                          zorder=3)
            elif edge in row["free_edges"].split("+"):
                axis.plot(xs, ys, color="#1E8449", lw=2.2, ls=(0, (4, 2)),
                          zorder=3)
            else:
                axis.plot(xs, ys, color="#555555", lw=1.4, zorder=3)

        #  material 1-axis
        cx, cy = 0.5 * (x0 + x1), 0.5 * (y0 + y1)
        angle = np.deg2rad(row["material_orientation_deg"])
        reach = 0.30 * min(x1 - x0, y1 - y0)
        axis.add_patch(FancyArrowPatch(
            (cx - reach * np.cos(angle), cy - reach * np.sin(angle)),
            (cx + reach * np.cos(angle), cy + reach * np.sin(angle)),
            arrowstyle="-|>", mutation_scale=11, lw=1.6, color="#6C3483",
            zorder=4))
        axis.text(cx + 1.15 * reach * np.cos(angle),
                  cy + 1.15 * reach * np.sin(angle), "1", color="#6C3483",
                  fontsize=8, ha="center", va="center", zorder=5)

        axis.set_aspect("equal")
        pad = 0.10 * max(x1 - x0, y1 - y0)
        axis.set_xlim(x0 - pad, x1 + pad)
        axis.set_ylim(y0 - pad, y1 + pad)
        #  Everything descriptive goes in the TITLE.  Putting it under the axis
        #  collides with the x-label once the panels are square-ish.
        axis.set_title(
            f"{row['name']}  (exp {row['experiment_id']})\n"
            f"$\\varphi$ = {row['material_orientation_deg']:.0f}$^\\circ$,  "
            f"{row['n_points']} pts $\\times$ {row['n_steps']} steps,  "
            f"mesh {row['mesh']}\n"
            f"length along ${row['length_axis']}$ = {row['length_mm']:.2f} mm,  "
            f"width {row['width_mm']:.2f} mm\n"
            f"area {row['sample_area_mm2']:.2f} mm$^2$",
            fontsize=7.0, pad=5)
        axis.set_xlabel(f"$x$ [mm]   [{x0:.2f}, {x1:.2f}]", fontsize=7)
        axis.set_ylabel(f"$y$ [mm]   [{y0:.2f}, {y1:.2f}]", fontsize=7)
        axis.tick_params(labelsize=6.5)

    handles = [
        plt.Line2D([], [], color="#C0392B", lw=2.6,
                   label="loaded cut  ($W$, tangential slope, $W_{XY}$ = 0;"
                         " normal rotation carries $M$)"),
        plt.Line2D([], [], color="#1E8449", lw=2.2, ls=(0, (4, 2)),
                   label="free edge  (unconstrained: $M_{nn}=0$, $V_n=0$)"),
        plt.Line2D([], [], color="#6C3483", lw=1.6, label="material 1-axis"),
    ]
    figure.legend(handles=handles, loc="lower center", frameon=False,
                  fontsize=6.6, ncol=1, bbox_to_anchor=(0.5, 0.002))
    figure.suptitle("Measurement windows and boundary conditions, to scale",
                    fontsize=9.5, y=0.99)
    figure.tight_layout(rect=(0, 0.13, 1, 0.945))
    save(figure, path)


# =============================================================================
#  Figures 2-4
# =============================================================================

def save(figure, path):
    FIGURES.mkdir(parents=True, exist_ok=True)
    figure.savefig(path.with_suffix(".pdf"))
    figure.savefig(path.with_suffix(".png"), dpi=600)
    plt.close(figure)
    print(f"  wrote figures/{path.name}.pdf + .png")


def figure_coefficients(results, path):
    """Unconstrained vs D12 >= 0, for the 2- and 3-coupon campaigns."""
    keys = list(results.keys())
    figure, axes = plt.subplots(1, 4, figsize=(7.16, 2.6))
    width = 0.36
    positions = np.arange(len(keys))
    for index, name in enumerate(LABELS):
        axis = axes[index]
        free = [results[k]["theta_free"][index] for k in keys]
        con = [results[k]["theta_con"][index] for k in keys]
        axis.bar(positions - width / 2, free, width, color=COLOURS[name],
                 alpha=0.45, label="unconstrained")
        axis.bar(positions + width / 2, con, width, color=COLOURS[name],
                 label="$D_{12}\\geq 0$")
        axis.axhline(0.0, color="#888888", lw=0.8)
        axis.set_xticks(positions)
        axis.set_xticklabels([k.replace(" ", "\n") for k in keys], fontsize=6.6)
        axis.set_title(math_label(name), fontsize=9.5)
        axis.tick_params(labelsize=7)
        soft_grid(axis)
        if index == 0:
            axis.set_ylabel("N$\\cdot$mm", fontsize=8)
            axis.legend(fontsize=6.2, frameon=False, loc="lower left")
    figure.suptitle("FGLS with and without the $D_{12}\\geq 0$ constraint",
                    fontsize=9.5, y=0.985)
    figure.tight_layout(rect=(0, 0, 1, 0.92))
    save(figure, path)


def figure_single_step(sweep, reference, path):
    """Coefficients from ONE load step per experiment, vs which step."""
    steps = [entry["step"] for entry in sweep]
    figure, axes = plt.subplots(1, 4, figsize=(7.16, 2.55))
    for index, name in enumerate(LABELS):
        axis = axes[index]
        free = [entry["theta_free"][index] for entry in sweep]
        con = [entry["theta_con"][index] for entry in sweep]
        axis.plot(steps, free, marker=MARKERS[name], ms=3.6, lw=1.2,
                  color=COLOURS[name], alpha=0.45, label="unconstrained")
        axis.plot(steps, con, marker=MARKERS[name], ms=3.6, lw=1.5,
                  color=COLOURS[name], label="$D_{12}\\geq0$")
        axis.axhline(reference["theta_con"][index], color="#333333", ls="--",
                     lw=1.1, label="all 9 steps, $D_{12}\\geq0$")
        axis.axhline(0.0, color="#999999", lw=0.7, ls=":")
        axis.set_title(math_label(name), fontsize=9.5)
        axis.set_xticks(steps)
        axis.set_xlabel("load step used (one per experiment)", fontsize=6.8)
        axis.tick_params(labelsize=7)
        soft_grid(axis)
        if index == 0:
            axis.set_ylabel("N$\\cdot$mm", fontsize=8)
            axis.legend(fontsize=5.8, frameon=False, loc="best")
    figure.suptitle("One load step per experiment (3 steps total) vs all nine "
                    "(27 total)", fontsize=9.5, y=0.985)
    figure.tight_layout(rect=(0, 0, 1, 0.92))
    save(figure, path)


def figure_constraint_cost(sweep, reference, path):
    """What the constraint costs, and whether the data ever objected."""
    figure, axes = plt.subplots(1, 2, figsize=(7.16, 2.5))
    steps = [entry["step"] for entry in sweep]

    axis = axes[0]
    axis.plot(steps, [e["chi2_free"] for e in sweep], marker="o", ms=4,
              lw=1.3, color="#555555", label="unconstrained")
    axis.plot(steps, [e["chi2_con"] for e in sweep], marker="s", ms=4,
              lw=1.3, color="#C55A11", label="$D_{12}\\geq0$")
    axis.set_yscale("log")
    axis.set_xlabel("load step used", fontsize=8)
    axis.set_ylabel("$\\chi^2$/dof", fontsize=8)
    axis.set_title("cost of the constraint in fit", fontsize=8.5)
    axis.legend(fontsize=6.5, frameon=False)
    axis.tick_params(labelsize=7)
    soft_grid(axis)

    axis = axes[1]
    values = [e["birge_q"] for e in sweep]
    axis.bar(steps, values, color="#C55A11", width=0.6)
    axis.axhline(3.84, color="#C0392B", ls="--", lw=1.1,
                 label="$\\chi^2_{1,\\,0.95}$ = 3.84")
    axis.axhline(reference["birge_q"], color="#333333", ls=":", lw=1.2,
                 label=f"all 9 steps = {reference['birge_q']:.2f}")
    axis.set_xlabel("load step used", fontsize=8)
    axis.set_ylabel("Birge-scaled $\\Delta Q$", fontsize=8)
    axis.set_title("is $D_{12}=0$ rejected?  (below the line = no)",
                   fontsize=8.5)
    axis.legend(fontsize=6.5, frameon=False)
    axis.tick_params(labelsize=7)
    soft_grid(axis)

    figure.suptitle("The constraint is nearly free, and never rejected",
                    fontsize=9.5, y=0.99)
    figure.tight_layout(rect=(0, 0, 1, 0.92))
    save(figure, path)


