def main() -> None:
    apply_style()
    FIGURES.mkdir(parents=True, exist_ok=True)
    DATA.mkdir(parents=True, exist_ok=True)

    # ---- setup ------------------------------------------------------------
    print("=" * 78)
    print("  EXPERIMENT SETUP  (read from each experiment's own files)")
    print("=" * 78)
    rows = experiment_setup()
    for row in rows:
        print(f"\n  {row['name']}  (experiment {row['experiment_id']}, "
              f"{row['bc_file']})")
        print(f"    material frame        phi = {row['material_orientation_deg']:.0f} deg"
              f"   (angle from this experiment's +x to the material 1-axis)")
        print(f"    length runs along     {row['length_axis']}")
        print(f"    WINDOW START / END    {row['length_axis']} = "
              f"{row['window_start_mm']:.4f} -> {row['window_end_mm']:.4f} mm"
              f"   (length {row['length_mm']:.3f} mm)")
        print(f"    full node bounds      x [{row['x_min']:.6f}, {row['x_max']:.6f}]  "
              f"y [{row['y_min']:.6f}, {row['y_max']:.6f}] mm")
        print(f"    virtual-mesh bounds   x [{row['mesh_x_min']:.6f}, {row['mesh_x_max']:.6f}]  "
              f"y [{row['mesh_y_min']:.6f}, {row['mesh_y_max']:.6f}] mm")
        print(f"    width                 {row['width_mm']:.3f} mm, "
              f"area {row['sample_area_mm2']:.4f} mm^2, mesh {row['mesh']}, "
              f"{row['n_points']} points x {row['n_steps']} steps")
        print(f"    FREE edges            {row['free_edges']}  "
              f"(unconstrained: M_nn = 0 and V_n = 0 there)")
        print(f"    LOADED cuts           {row['loaded_edges']}")
        print(f"    clamped DOFs          {row['clamped_dofs']}")
        print(f"    external work         {row['external_dof']}")

    with (DATA / "experiment_setup.csv").open("w", newline="",
                                              encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0].keys()))
        writer.writeheader()
        writer.writerows(rows)
    print(f"\n  wrote data/experiment_setup.csv")

    figure_setup(rows, FIGURES / "fig1_setup")

    # ---- all steps --------------------------------------------------------
    print()
    print("=" * 78)
    print("  IDENTIFICATION, ALL LOAD STEPS")
    print("=" * 78)
    results = {}
    for tag, tests in (("2 coupons", TESTS), ("3 coupons", TESTS_WITH_45_RAW)):
        cases, ids = build(tests)
        row = identify(cases, ids)
        results[tag] = row
        print(f"\n  {tag}  ({len(cases)} load steps)")
        print(f"    {'':<18}" + "".join(f"{n:>11}" for n in LABELS)
              + f"{'chi2/dof':>11}")
        print(f"    {'unconstrained':<18}"
              + "".join(f"{v:11.3f}" for v in row["theta_free"])
              + f"{row['chi2_free']:11.0f}")
        print(f"    {'D12 >= 0':<18}"
              + "".join(f"{v:11.3f}" for v in row["theta_con"])
              + f"{row['chi2_con']:11.0f}")
        if row["active"]:
            print(f"    constraint ACTIVE.  DeltaQ = {row['delta_q']:.1f}, "
                  f"Birge-scaled = {row['birge_q']:.2f}, p = {row['p_value']:.3f}")
            print(f"    projection vs column-deletion: {row['agreement']:.2e}")
        else:
            print(f"    constraint INACTIVE (D12 = "
                  f"{row['theta_free'][K_D12]:+.3f} >= 0 already)")

    figure_coefficients(results, FIGURES / "fig2_coefficients")

    # ---- one step per experiment -----------------------------------------
    print()
    print("=" * 78)
    print("  ONE LOAD STEP PER EXPERIMENT  (3 steps total, not 27)")
    print("=" * 78)
    print("  Step 1 here is the first EXPORTED step, which is step 3 of the")
    print("  original ramp -- the exports drop step 1 and reference on step 2.")
    print()
    print(f"  {'step':>5}" + "".join(f"{n:>11}" for n in LABELS)
          + f"{'chi2/dof':>11}{'BirgeQ':>9}{'p':>8}{'dQ/Q*':>10}{'projErr':>11}")
    sweep = []
    for index in range(len(mat_files(TESTS_WITH_45_RAW[0]))):
        cases, ids = build(TESTS_WITH_45_RAW, step_index=index)
        row = identify(cases, ids)
        row["step"] = index + 1
        sweep.append(row)
        print(f"  {index + 1:>5}"
              + "".join(f"{v:11.3f}" for v in row["theta_con"])
              + f"{row['chi2_con']:11.0f}{row['birge_q']:9.2f}"
              + f"{row['p_value']:8.3f}"
              + f"{row['q_penalty'] / max(row['q_star'], 1e-30):10.2e}"
              + f"{row['projection_error']:11.1e}")

    stack = np.array([row["theta_con"] for row in sweep])
    span = stack.max(axis=0) - stack.min(axis=0)
    middle = np.abs(0.5 * (stack.max(axis=0) + stack.min(axis=0)))
    print(f"  {'spread %':>5}"
          + "".join(f"{v:11.1f}" for v in 100.0 * span / np.maximum(middle, 1e-12)))
    print(f"  {'all 9':>5}"
          + "".join(f"{v:11.3f}" for v in results["3 coupons"]["theta_con"])
          + f"{results['3 coupons']['chi2_con']:11.0f}")

    figure_single_step(sweep, results["3 coupons"],
                       FIGURES / "fig3_single_step")
    figure_constraint_cost(sweep, results["3 coupons"],
                           FIGURES / "fig4_constraint_cost")

    with (DATA / "results.csv").open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["case", "constraint", *LABELS, "chi2_per_dof",
                         "delta_q", "birge_q", "p_value"])
        for tag, row in results.items():
            writer.writerow([tag, "none", *[f"{v:.6f}" for v in row["theta_free"]],
                             f"{row['chi2_free']:.3f}", "", "", ""])
            writer.writerow([tag, "D12>=0", *[f"{v:.6f}" for v in row["theta_con"]],
                             f"{row['chi2_con']:.3f}", f"{row['delta_q']:.3f}",
                             f"{row['birge_q']:.4f}", f"{row['p_value']:.4f}"])
        for row in sweep:
            writer.writerow([f"3 coupons, step {row['step']} only", "none",
                             *[f"{v:.6f}" for v in row["theta_free"]],
                             f"{row['chi2_free']:.3f}", "", "", ""])
            writer.writerow([f"3 coupons, step {row['step']} only", "D12>=0",
                             *[f"{v:.6f}" for v in row["theta_con"]],
                             f"{row['chi2_con']:.3f}", f"{row['delta_q']:.3f}",
                             f"{row['birge_q']:.4f}", f"{row['p_value']:.4f}"])
    print(f"\n  wrote data/results.csv")


if __name__ == "__main__":
    main()
